<?php
declare(strict_types=1);
const SOLTAN_MCP_RESOURCE='https://soltan.toseno.ir/mcp.php';
const SOLTAN_OAUTH_ISSUER='https://soltan.toseno.ir';
function mo_file():string {return __DIR__.'/storage/mcp/oauth.json';}
function mo_data():array { $f=mo_file();$x=is_file($f)?json_decode((string)file_get_contents($f),true):null;return is_array($x)?$x:['clients'=>[],'codes'=>[],'refresh'=>[]];}
function mo_save(array $data):void {$f=mo_file();$dir=dirname($f);if(!is_dir($dir))mkdir($dir,0700,true);@chmod($dir,0700);file_put_contents($dir.'/.htaccess',"Require all denied\nDeny from all\n");$tmp=$f.'.'.bin2hex(random_bytes(6));if(file_put_contents($tmp,json_encode($data,JSON_UNESCAPED_SLASHES),LOCK_EX)===false)throw new RuntimeException('Write failed');chmod($tmp,0600);if(!rename($tmp,$f))throw new RuntimeException('Commit failed');}
function mo_locked(callable $fn):mixed {$dir=dirname(mo_file());if(!is_dir($dir))mkdir($dir,0700,true);$f=fopen($dir.'/oauth.lock','c');if(!$f||!flock($f,LOCK_EX))throw new RuntimeException('OAuth lock failed');try{$d=mo_data();$v=$fn($d);mo_save($d);return $v;}finally{flock($f,LOCK_UN);fclose($f);}}
function mo_rand(int $n=32):string{return rtrim(strtr(base64_encode(random_bytes($n)),'+/','-_'),'=');}
function mo_json(array $data,int $status=200):never {http_response_code($status);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');echo json_encode($data,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);exit;}
function mo_error(string $error,int $status=400):never {mo_json(['error'=>$error],$status);}
function mo_valid_redirect(string $uri):bool {if(strlen($uri)>1000||str_contains($uri,'#'))return false;$p=parse_url($uri);if(!$p||!isset($p['scheme'],$p['host'])||isset($p['user'])||isset($p['pass']))return false;return $p['scheme']==='https'||($p['scheme']==='http'&&in_array($p['host'],['localhost','127.0.0.1','[::1]'],true));}
function mo_default_scopes(string $role):string {return $role==='developer'?'read:companies read:panels read:customers read:reports admin:diagnostics':'read:companies read:panels read:customers read:reports';}
function mo_scopes(string $s,string $role):array { $allowed=['read:companies','read:panels','read:customers','read:reports'];if(in_array($role,['developer','admin'],true))$allowed[]='write:companies';if(in_array($role,['developer','admin'],true))$allowed[]='write:customers';if(in_array($role,['developer','admin'],true))$allowed[]='write:transfers';if($role==='developer')$allowed[]='admin:diagnostics';if($role==='developer')$allowed[]='admin:backup';$r=array_unique(array_filter(explode(' ',trim($s))));if(!$r)$r=['read:companies'];foreach($r as $v)if(!in_array($v,$allowed,true))throw new RuntimeException('invalid_scope');return array_values($r);}
function mo_client(string $id):?array{$d=mo_data();return $d['clients'][$id]??null;}
function mo_token(string $userId,string $securityVersion,array $scopes,string $clientId,int $life=900):string{$token=mo_rand(48);$file=__DIR__.'/storage/mcp/credentials.json';$d=is_file($file)?json_decode((string)file_get_contents($file),true):null;if(!is_array($d))$d=['entries'=>[]];$d['entries'][]=['hash'=>hash('sha256',$token),'user_id'=>(int)$userId,'security_version'=>(int)$securityVersion,'scopes'=>$scopes,'expires_at'=>time()+$life,'client_id'=>$clientId,'audience'=>SOLTAN_MCP_RESOURCE];$tmp=$file.'.'.mo_rand(8);file_put_contents($tmp,json_encode($d),LOCK_EX);chmod($tmp,0600);rename($tmp,$file);return $token;}
